    t=ast.parse(open(m+'.py',encoding='utf-8').read())
    deps=set()
    for n in ast.walk(t):
        if isinstance(n,ast.Import):
            for a in n.names:
                if a.name in mods: deps.add((a.name,'top' if n in t.body else 'lazy'))
        elif isinstance(n,ast.ImportFrom) and n.module in mods:
            deps.add((n.module,'top' if n in t.body else 'lazy'))
